import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import AnimatedText from '../components/AnimatedText';
import './FAQ.css';

const faqs = [
  { q: "What services does Casser Photography offer?", a: "We provide photography and videography services such as weddings, pre-weddings, maternity shoots, fashion portfolios, corporate events, product shoots, drone coverage, and more—all across India." },
  { q: "Do you have a studio?", a: "Yes, we have a fully equipped studio located in Delhi for professional shoots like portraits, product photography, and portfolios." },
  { q: "Where are you located?", a: "Shop no. 6, DDA Shopping Complex, Ashok Vihar, Phase-1, Block-B, Delhi-110052.\nLandmark: Golden Bell School." },
  { q: "Do you provide services outside Delhi?", a: "Yes, we offer services across all of India. Our team is available to travel for shoots and events." },
  { q: "How can I book your services?", a: "You can contact us at:\n+91-9971330781\n+91-9599893508\n+91-7042570781\nto discuss availability and packages." },
  { q: "What are your working hours?", a: "Monday to Saturday: 10:00 AM – 7:00 PM\nSunday: 10:00 AM – 5:00 PM" },
  { q: "Do you offer customizable packages?", a: "Yes, we customize packages based on your event, needs, and budget to ensure a personalized experience." },
  { q: "How far in advance should I book?", a: "We recommend booking at least 1–2 months in advance, especially for weddings and large events." },
  { q: "Do you offer drone and cinematic videography?", a: "Yes, we specialize in drone and cinematic video coverage to make your moments more dynamic and memorable." },
  { q: "Can I visit your studio before booking?", a: "Absolutely! Just give us a call to schedule a visit to our studio and meet the team." }
];

const FAQ = () => {
  const [activeIndex, setActiveIndex] = useState(null);

  const toggleFAQ = (index) => {
    setActiveIndex(activeIndex === index ? null : index);
  };

  return (
    <div className="page faq-page">
      <section className="section-padding container">
        <div className="section-header center-header">
          <AnimatedText text="Frequently Asked Questions" el="h1" className="section-title" />
          <p className="section-subtitle">Everything you need to know about our services and booking process.</p>
        </div>

        <div className="faq-container">
          {faqs.map((faq, index) => (
            <motion.div 
              key={index}
              className={`faq-item ${activeIndex === index ? 'active' : ''}`}
              initial={{ opacity: 0, y: 20 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true, margin: "-50px" }}
              transition={{ duration: 0.5, delay: index * 0.05 }}
            >
              <div 
                className="faq-question" 
                onClick={() => toggleFAQ(index)}
              >
                <h3>{faq.q}</h3>
                <span className="faq-icon">{activeIndex === index ? '−' : '+'}</span>
              </div>
              
              <AnimatePresence>
                {activeIndex === index && (
                  <motion.div 
                    className="faq-answer"
                    initial={{ height: 0, opacity: 0 }}
                    animate={{ height: 'auto', opacity: 1 }}
                    exit={{ height: 0, opacity: 0 }}
                    transition={{ duration: 0.3 }}
                  >
                    <div className="faq-answer-inner">
                      {faq.a.split('\n').map((line, i) => (
                        <p key={i}>{line}</p>
                      ))}
                    </div>
                  </motion.div>
                )}
              </AnimatePresence>
            </motion.div>
          ))}
        </div>
      </section>
    </div>
  );
};

export default FAQ;
